public int maxDepth(TreeNode root) {
    if (root == null) return 0;
    List<List<Integer>> paths = new ArrayList<>();
    collect(root, new ArrayList<>(), paths);
    int best = 0;
    for (List<Integer> p : paths) best = Math.max(best, p.size());
    return best;
}

void collect(TreeNode node, List<Integer> path, List<List<Integer>> paths) {
    List<Integer> next = new ArrayList<>(path);   // copy the path at every node
    next.add(node.val);
    if (node.left == null && node.right == null) {
        paths.add(next);
        return;
    }
    if (node.left != null) collect(node.left, next, paths);
    if (node.right != null) collect(node.right, next, paths);
}

void collect(TreeNode* node, vector<int> path, vector<vector<int>>& paths) {
    path.push_back(node->val);              // path is a copy: copied at every node
    if (!node->left && !node->right) {
        paths.push_back(path);
        return;
    }
    if (node->left) collect(node->left, path, paths);
    if (node->right) collect(node->right, path, paths);
}

int maxDepth(TreeNode* root) {
    if (root == nullptr) return 0;
    vector<vector<int>> paths;
    collect(root, {}, paths);
    size_t best = 0;
    for (const auto& p : paths) best = max(best, p.size());
